     4	import { reimbursementRateOf } from "./reimbursement-clause.js";
     5	
     6	export interface Damage {
     7	  readonly itemType: string;
     8	  readonly amount: number;
     9	}
    10	
    11	export interface ClaimResult {
    12	  readonly payout: number;
    13	  readonly remainingCap: number;
    14	}
    15	
    16	/**
    17	 * The policyholder bears a deductible on each damaged item, so an incident
    18	 * that damages several items bears it several times -- once per damage
    19	 * entry, which is why the payout is accumulated per entry rather than off
    20	 * the incident's total.
    21	 */
    22	const DEDUCTIBLE = 100;
    23	
    24	/**
    25	 * A payout is money the MHPCO pays out, so it floors at nothing: the
    26	 * deductible can reduce a payout to zero, but a damage smaller than the
    27	 * deductible never turns into a debt owed to the MHPCO.
    28	 */
    29	const NOTHING_PAID_OUT = 0;
    30	
    31	/** What one damage settles at: the reimbursed share, less the deductible. */
    32	/**
    33	 * A damage is an amount of harm suffered, so it cannot be negative: a
    34	 * negative entry is a malformed report, not a claim the MHPCO settles.
    35	 */
    36	function damageAmountOf(damage: Damage): number {
    37	  if (damage.amount < NOTHING_PAID_OUT) {
    38	    throw new Error(
    39	      `A damage cannot be a negative amount, but got ${damage.amount}`,
    40	    );
    41	  }
    42	  return damage.amount;
    43	}
    44	
    45	function payoutForDamage(damagedItem: Item, damage: Damage): number {
    46	  const reimbursed = damageAmountOf(damage) * reimbursementRateOf(damagedItem);
    47	  return Math.max(reimbursed - DEDUCTIBLE, NOTHING_PAID_OUT);
    48	}
    49	
    50	/**
    51	 * What an incident settles at: each damage entry is settled on its own --
    52	 * under the clauses of the item it hit, and bearing its own deductible --
    53	 * and the entries accumulate. An incident that damages nothing settles at
    54	 * nothing.
    55	 */
    56	function incidentPayout(
    57	  items: readonly Item[],
    58	  damages: readonly Damage[],
    59	): number {
    60	  const hit = damagedItems(
    61	    items,
    62	    damages.map((damage) => damage.itemType),
    63	  );
    64	  return damages.reduce(
    65	    (total, damage, entry) => total + payoutForDamage(hit[entry], damage),
    66	    NOTHING_PAID_OUT,
    67	  );
    68	}
    69	
    70	/** What a draw against the cap takes, and what it leaves behind. */
    71	interface CapDraw {
    72	  readonly drawn: number;
    73	  readonly remainingCap: number;
    74	}
    75	
    76	/**
    77	 * The policy pays no more than its cap still allows, so a payout the cap
    78	 * cannot cover is reduced to what is left of it -- and once the cap is
    79	 * exhausted it draws nothing at all.
    80	 *
    81	 * What a draw takes and what it leaves are one fact about the cap, stated
    82	 * here together so that neither can be revised without the other.
    83	 *
    84	 * The cap is a separate limit from the clauses and the deductible: those
    85	 * decide what the MHPCO owes for a damage, whereas the cap decides how much
    86	 * a policy can still pay out at all, and the MHPCO revises the two on their
    87	 * own schedules -- which is why drawing against the cap is stated apart from
    88	 * what a damage settles at.
    89	 */
    90	function drawAgainstCap(capBeforeClaim: number, desiredPayout: number): CapDraw {
    91	  const drawn = Math.min(desiredPayout, capBeforeClaim);
    92	  return { drawn, remainingCap: capBeforeClaim - drawn };
    93	}
    94	
    95	/**
    96	 * What the incident settles at as a final payout: whole G, rounded in the
    97	 * MHPCO's favour.
    98	 *
    99	 * The rounding happens here, before the cap is drawn against, rather than on
   100	 * whatever the draw yields. The clauses and the deductible are the
   101	 * calculation, and its result is the final payout the spec has rounded; the
   102	 * cap is a limit applied to that finished amount, not a further step of the
   103	 * calculation. Rounding first is also what keeps the cap's ledger honest:
   104	 * the policy is debited exactly the whole G it pays out, so the payout and
   105	 * the remaining cap always add back up to the cap before the claim.
   106	 *
   107	 * Under the present rules the alternative ordering is indistinguishable --
   108	 * a cap is always whole G, so a draw that binds yields that same whole
   109	 * number either way -- which is precisely why the choice is stated here by
   110	 * name instead of being left implicit in the order of two calls.
   111	 */
   112	function finalPayoutFor(
   113	  items: readonly Item[],
   114	  damages: readonly Damage[],
   115	): number {
   116	  return payoutRoundedInMHPCOsFavour(incidentPayout(items, damages));
   117	}
   118	
   119	/**
   120	 * Settling an incident against the policy that covers it: what the incident
   121	 * settles at, and what it leaves of the policy's cap.
   122	 */
   123	export function claim(
   124	  items: readonly Item[],
   125	  damages: readonly Damage[],
   126	  capBeforeClaim: number,
   127	): ClaimResult {
   128	  const { drawn, remainingCap } = drawAgainstCap(
   129	    capBeforeClaim,
   130	    finalPayoutFor(items, damages),
   131	  );
   132	  return { payout: drawn, remainingCap };
   133	}
